--!strict
-- The game's XML configs as generated by tools/build_game.py: {t=tag, a=attrs, c=children, x=text}.
-- Attribute values are the original strings. Big documents keep children in part modules (p = names),
-- joined here on first load.

local Data = script.Parent.Data

local Xml = {}

export type Element = { t: string, a: { [string]: string }?, c: { Element }?, x: string?, p: { string }? }

local function resolve(folder: Instance, el: any)
	if el.p then
		local kids = {}
		for _, name in el.p do
			for _, k in require(folder:FindFirstChild(name) :: ModuleScript) :: any do
				table.insert(kids, k)
			end
		end
		el.c = kids
		el.p = nil
	end
	if el.c then
		for _, k in el.c do
			if k.p or k.c then resolve(folder, k) end
		end
	end
end

local cache = {}
local function load(folderName: string, name: string): Element?
	local key = folderName .. "/" .. name
	local hit = cache[key]
	if hit ~= nil then return hit or nil end
	local folder = Data:FindFirstChild(folderName)
	local mod = folder and folder:FindFirstChild(name)
	if not mod then
		cache[key] = false
		return nil
	end
	local root = require(mod :: ModuleScript) :: any
	resolve(folder :: Instance, root)
	cache[key] = root
	return root
end

-- A config document (out/Xml/<name>.lua), e.g. Xml.doc("stages")
function Xml.doc(name: string): Element
	return assert(load("Xml", name), "no document " .. name)
end

-- A location layout (<name>_params), or nil
function Xml.location(name: string): Element?
	return load("Locations", name)
end

function Xml.attr(el: Element?, name: string, default: string?): string?
	local a = el and el.a
	local v = a and a[name]
	if v == nil then return default end
	return v
end

function Xml.num(el: Element?, name: string, default: number?): number?
	local v = Xml.attr(el, name)
	return v and tonumber(v) or default
end

function Xml.bool(el: Element?, name: string): boolean
	local v = Xml.attr(el, name)
	return v == "1" or v == "true" or v == "True"
end

-- First child with this tag (or nil)
function Xml.first(el: Element?, tag: string): Element?
	if not el or not el.c then return nil end
	for _, k in el.c do
		if k.t == tag then return k end
	end
	return nil
end

-- Children with this tag (all children if tag is nil)
function Xml.all(el: Element?, tag: string?): { Element }
	local out = {}
	if not el or not el.c then return out end
	for _, k in el.c do
		if tag == nil or k.t == tag then table.insert(out, k) end
	end
	return out
end

-- Follow a path of tags: Xml.path(root, "Zones", "Zone")
function Xml.path(el: Element?, ...: string): Element?
	local cur = el
	for _, tag in { ... } do
		cur = Xml.first(cur, tag)
		if not cur then return nil end
	end
	return cur
end

-- Localized text (out/Lang/<lang>.lua, Word Title -> text). Unknown keys come back as the key.
local langName = "eng"
local lang: { [string]: string }? = nil
function Xml.setLanguage(name: string)
	langName = name
	lang = nil
end
function Xml.language(): string
	return langName
end
function Xml.text(key: string?): string
	if not key or key == "" then return "" end
	if not lang then
		local folder = Data:FindFirstChild("Lang")
		local mod = folder and (folder:FindFirstChild(langName) or folder:FindFirstChild("eng"))
		lang = mod and require(mod :: ModuleScript) :: any or {}
	end
	return (lang :: any)[key] or key
end

return Xml
